import { test, expect } from '@playwright/test';

test.describe('Login Form CAPTCHA After Failed Attempts', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display CAPTCHA after 3 failed login attempts', async ({ page }) => {
    // First failed attempt
    await page.route('**/api/auth/login', async (route) => {
      await route.abort('failed');
    });
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('wrongpassword');
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Second failed attempt
    await page.route('**/api/auth/login', async (route) => {
      await route.abort('failed');
    });
    await emailInput.fill('user@example.com');
    await passwordInput.fill('wrongpassword');
    await submitButton.click();

    // Third failed attempt
    await page.route('**/api/auth/login', async (route) => {
      await route.abort('failed');
    });
    await emailInput.fill('user@example.com');
    await passwordInput.fill('wrongpassword');
    await submitButton.click();

    // Verify CAPTCHA is displayed
    const captchaContainer = page.getByRole('region', { name: /captcha/i });
    await expect(captchaContainer).toBeVisible();

    const captchaImage = page.getByRole('img', { name: /captcha/i });
    await expect(captchaImage).toBeVisible();

    const captchaInput = page.getByLabel('Enter Captcha');
    await expect(captchaInput).toBeVisible();

    // Verify CAPTCHA input is enabled
    await expect(captchaInput).toBeEnabled();

    // Verify login button is disabled
    const loginButton = page.getByRole('button', { name: /submit/i });
    await expect(loginButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/too many failed attempts/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should not display CAPTCHA after successful login', async ({ page }) => {
    // First failed attempt
    await page.route('**/api/auth/login', async (route) => {
      await route.abort('failed');
    });
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('user@example.com');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('correctpassword');
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify CAPTCHA is not displayed
    const captchaContainer = page.getByRole('region', { name: /captcha/i });
    await expect(captchaContainer).not.toBeVisible();

    // Verify login button is enabled
    const loginButton = page.getByRole('button', { name: /submit/i });
    await expect(loginButton).toBeEnabled();

    // Verify success message is displayed
    const successMessage = page.getByText(/login successful/i);
    await expect(successMessage).toBeVisible();
  });
});
